PasswordReset = {
  init: async function (app, container) {
    app = app || session.app;
    container = container || $(".component[name=PasswordReset]");
    $("button[name=submitReset]", container).on("click", async function (event) { event.preventDefault(); await PasswordReset.confirm(app, container); });
  },
  confirm: async function (app, container) {
    var url = new URL(window.location.href);
    var resetRequest = { UserId: url.searchParams.get("uid"), NewPassword: $("input[name=pass]", container).val(), ConfirmPassword: $("input[name=confirm]", container).val(), Token: url.searchParams.get("token"), SourceAppId: app.Id };
    var result = await api.post("Account/ConfirmForgotPassword", resetRequest);
    if (!(result || result === "")) { notification.error("[resource_description[ResetFailed]]"); return; }
    notification.success("[resource_description[ResetSuccess]]");
    var loginResult = await api.login(resetRequest.UserId, resetRequest.NewPassword, true);
    if (loginResult) { window.location.href = "/"; return; }
    notification.error("[resource_description[ResetLoginFailed]]");
  }
};
$(function () { PasswordReset.init(); });
